const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const bhadlaPark = ee.Geometry.Point([71.91, 27.54]).buffer(10000); // 10km buffer around known location
  const startDate = '2022-01-01';
  const endDate = '2022-01-31';

  // 2. Data Acquisition - Sentinel-2 for solar panel detection
  let s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(bhadlaPark)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

  // Check if collection is empty
  const s2Count = s2Col.size().getInfo();
  console.log(`January 2022 Images: ${s2Count}`);

  if (s2Count === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mosaic and detect solar panels
  const mosaic = s2Col.median();

  // Solar panel detection using spectral characteristics
  // Solar panels typically have low NDVI, high reflectance in visible/NIR
  const ndvi = mosaic.normalizedDifference(['B8', 'B4']).rename('NDVI');
  const ndwi = mosaic.normalizedDifference(['B3', 'B8']).rename('NDWI');

  // Create solar panel mask (low vegetation, high reflectance)
  const solarMask = ndvi.lt(0.2)  // Low vegetation index
    .and(mosaic.select('B8').gt(2000))  // High NIR reflectance
    .and(ndwi.lt(0.1))  // Low water index
    .and(mosaic.select('B4').lt(3000));  // Moderate red reflectance

  // 4. Calculate area
  const areaImage = solarMask.multiply(ee.Image.pixelArea()); // Area in m²
  const areaStats = areaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: bhadlaPark,
    scale: 100,
    maxPixels: 1e9
  });

  const areaM2 = areaStats.get('NDVI').getInfo();
  console.log(`Area in m²: ${areaM2}`);

  // Check for valid pixels
  if (areaM2 === null || areaM2 === undefined) {
    console.log("<answer>C3</answer>");
    return;
  }

  const pixelCount = solarMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bhadlaPark,
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Solar panel pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Convert to hectares (1 ha = 10,000 m²)
  const areaHectares = areaM2 / 10000;
  console.log(`Solar panel area: ${areaHectares.toFixed(2)} hectares`);

  // 5. Validation & Final Answer
  if (areaHectares > 7000) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
